-- Generated seed schema (SQLite/PostgreSQL-compatible subset)
PRAGMA foreign_keys = OFF;

CREATE TABLE actors (
  actor_id TEXT NOT NULL PRIMARY KEY,
  display_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('SYSTEM','INSTRUCTOR','ACADEMIC_ADMIN','SUPPORT_STAFF','PLATFORM_ADMIN')),
  email TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','INACTIVE'))
);

CREATE TABLE issuers (
  issuer_id TEXT NOT NULL PRIMARY KEY,
  issuer_name TEXT NOT NULL UNIQUE,
  issuer_type TEXT NOT NULL CHECK (issuer_type IN ('UNIVERSITY','TRAINING_PROVIDER','PROFESSIONAL_BODY')),
  country TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','SUPERSEDED')),
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  predecessor_issuer_id TEXT,
  signing_key_id TEXT NOT NULL UNIQUE,
  key_fingerprint TEXT NOT NULL UNIQUE,
  FOREIGN KEY (predecessor_issuer_id) REFERENCES issuers(issuer_id)
);

CREATE TABLE learners (
  learner_id TEXT NOT NULL PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  full_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  date_of_birth TEXT NOT NULL,
  country TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED','CLOSED')),
  created_at TEXT NOT NULL
);

CREATE TABLE courses (
  course_id TEXT NOT NULL PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  level TEXT NOT NULL CHECK (level IN ('BEGINNER','INTERMEDIATE','ADVANCED')),
  credit_hours INTEGER NOT NULL,
  duration_days INTEGER NOT NULL,
  num_assessments INTEGER NOT NULL,
  instructor_id TEXT NOT NULL,
  issuer_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','RETIRED')),
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  FOREIGN KEY (instructor_id) REFERENCES actors(actor_id),
  FOREIGN KEY (issuer_id) REFERENCES issuers(issuer_id)
);

CREATE TABLE course_issuer_history (
  history_id TEXT NOT NULL PRIMARY KEY,
  course_id TEXT NOT NULL,
  issuer_id TEXT NOT NULL,
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  change_reason TEXT NOT NULL CHECK (change_reason IN ('INITIAL','ISSUER_SUCCESSION','ISSUER_TRANSFER')),
  FOREIGN KEY (course_id) REFERENCES courses(course_id),
  FOREIGN KEY (issuer_id) REFERENCES issuers(issuer_id)
);

CREATE TABLE credential_rules (
  rule_id TEXT NOT NULL PRIMARY KEY,
  course_id TEXT NOT NULL,
  rule_version INTEGER NOT NULL,
  min_progress_pct INTEGER NOT NULL,
  min_assessments INTEGER NOT NULL,
  min_final_score INTEGER NOT NULL,
  min_attendance_pct INTEGER NOT NULL,
  validity_months INTEGER,
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','SUPERSEDED','RETIRED')),
  FOREIGN KEY (course_id) REFERENCES courses(course_id)
);

CREATE TABLE completion_records (
  completion_id TEXT NOT NULL PRIMARY KEY,
  learner_id TEXT NOT NULL,
  course_id TEXT NOT NULL,
  rule_id TEXT NOT NULL,
  enrolled_at TEXT NOT NULL,
  closed_at TEXT,
  completed_at TEXT,
  status TEXT NOT NULL CHECK (status IN ('IN_PROGRESS','COMPLETED','FAILED','WITHDRAWN')),
  progress_pct INTEGER NOT NULL,
  assessments_taken INTEGER NOT NULL,
  final_score REAL,
  attendance_pct REAL NOT NULL,
  requirements_met INTEGER NOT NULL,
  failure_reasons TEXT,
  FOREIGN KEY (learner_id) REFERENCES learners(learner_id),
  FOREIGN KEY (course_id) REFERENCES courses(course_id),
  FOREIGN KEY (rule_id) REFERENCES credential_rules(rule_id)
);

CREATE TABLE assessments (
  assessment_id TEXT NOT NULL PRIMARY KEY,
  completion_id TEXT NOT NULL,
  sequence_no INTEGER NOT NULL,
  assessment_type TEXT NOT NULL CHECK (assessment_type IN ('QUIZ','PROJECT','FINAL_EXAM')),
  score INTEGER NOT NULL,
  max_score INTEGER NOT NULL,
  taken_at TEXT NOT NULL,
  FOREIGN KEY (completion_id) REFERENCES completion_records(completion_id)
);

CREATE TABLE credentials (
  credential_id TEXT NOT NULL,
  completion_id TEXT NOT NULL UNIQUE,
  learner_id TEXT NOT NULL,
  course_id TEXT NOT NULL,
  rule_id TEXT NOT NULL,
  issuer_id TEXT NOT NULL,
  issued_at TEXT NOT NULL,
  expires_at TEXT,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','REVOKED','EXPIRED')),
  status_as_of TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  payload_hash TEXT NOT NULL,
  hash_algo TEXT NOT NULL CHECK (hash_algo IN ('SHA-256')),
  signature TEXT NOT NULL,
  signature_alg TEXT NOT NULL CHECK (signature_alg IN ('HMAC-SHA256')),
  signing_key_id TEXT NOT NULL,
  FOREIGN KEY (completion_id) REFERENCES completion_records(completion_id),
  FOREIGN KEY (learner_id) REFERENCES learners(learner_id),
  FOREIGN KEY (course_id) REFERENCES courses(course_id),
  FOREIGN KEY (rule_id) REFERENCES credential_rules(rule_id),
  FOREIGN KEY (issuer_id) REFERENCES issuers(issuer_id)
);
-- credential_id is the LOGICAL primary key; it is deliberately not UNIQUE here because the
-- injected DUPLICATE_CREDENTIAL_ID anomaly rows must be loadable and detectable by validation.
CREATE INDEX idx_credentials_credential_id ON credentials(credential_id);

CREATE TABLE revocations (
  revocation_id TEXT NOT NULL PRIMARY KEY,
  credential_id TEXT NOT NULL,
  revocation_seq INTEGER NOT NULL,
  revoked_at TEXT NOT NULL,
  reason_code TEXT NOT NULL CHECK (reason_code IN ('ISSUED_IN_ERROR','ACADEMIC_MISCONDUCT','LEARNER_REQUEST','FRAUD','POLICY_VIOLATION','COURSE_RETIRED')),
  revoked_by_actor_id TEXT NOT NULL,
  FOREIGN KEY (revoked_by_actor_id) REFERENCES actors(actor_id)
);

CREATE TABLE verification_requests (
  verification_id TEXT NOT NULL PRIMARY KEY,
  credential_id TEXT NOT NULL,
  requested_at TEXT NOT NULL,
  requester_type TEXT NOT NULL CHECK (requester_type IN ('EMPLOYER','UNIVERSITY','BACKGROUND_CHECK','LEARNER','GOVERNMENT')),
  requester_org TEXT NOT NULL,
  channel TEXT NOT NULL CHECK (channel IN ('API','PORTAL','EMAIL')),
  claimed_name TEXT,
  claimed_dob TEXT,
  claimed_email_hash TEXT,
  presented_payload_hash TEXT,
  result TEXT NOT NULL CHECK (result IN ('VALID','REVOKED','EXPIRED','NOT_FOUND','HASH_MISMATCH','IDENTITY_MISMATCH','INSUFFICIENT_IDENTITY','AMBIGUOUS_ID')),
  result_detail TEXT NOT NULL,
  response_ms INTEGER NOT NULL
);

CREATE TABLE audit_events (
  audit_event_id TEXT NOT NULL PRIMARY KEY,
  event_ts TEXT NOT NULL,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('Course','CredentialRule','CompletionRecord','Credential','VerificationRequest')),
  entity_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('RULE_PUBLISHED','ISSUER_CHANGED','LEARNER_ENROLLED','COMPLETION_STATE_CHANGED','CREDENTIAL_ISSUED','CREDENTIAL_REVOKED','REVOCATION_REVERSED','CREDENTIAL_EXPIRED','VERIFICATION_PERFORMED')),
  actor_type TEXT NOT NULL CHECK (actor_type IN ('SYSTEM','LEARNER','STAFF','EXTERNAL_VERIFIER')),
  actor_id TEXT NOT NULL,
  old_state TEXT,
  new_state TEXT,
  details_json TEXT NOT NULL,
  prev_event_hash TEXT NOT NULL,
  event_hash TEXT NOT NULL UNIQUE
);


-- Ground truth is intentionally NOT loaded here (see ground_truth.csv).
